    root.querySelectorAll('[data-variant-image-upload]').forEach(x=>x.addEventListener('change',async e=>{syncProductEditor();const i=Number(x.dataset.variantImageUpload),file=e.target.files?.[0];if(!file)return;try{const url=await B.uploadImage(file,'variants'),color=String(state.editor.variants[i]?.color||'').trim();if(state.editor.type==='Colour + Option'&&color)state.editor.variants.forEach(v=>{if(String(v.color||'').trim().toLowerCase()===color.toLowerCase())v.image=url;});else state.editor.variants[i].image=url;render();}catch(err){notify(err.message||'Option image upload failed');}}));
